            if i % 2 == 1:
                grid[r][c + (i + 1)] = 2
            else:
                grid[r][c + i] = 2

        # Lower half symmetric
        for i in range(r + 1):
            if i % 2 == 1:
                grid[r][c - (i + 1)] = 2
            else:
                grid[r][c - i] = 2

    # Add 1s at interior positions
    for r in range(n):
        for c_idx in range(n):
            d = abs(r - c) + abs(c_idx - c)
            if d == 0:  # center
                grid[r][c_idx] = 2
            elif 1 <= d <= c - 2:  # interior
                if d % 2 == 1 or abs(r - c) % 2 != 0 or abs(c_idx - c) % 2 != 0:
